sql.where:
R.MEMBER_NO = #{memberNo}

  AND R.STATUS = #{status}


  AND R.TYPE_NO = #{typeNo}


  AND R.CONTENT LIKE CONCAT('%', #{keyword}, '%')


  AND R.ROUTE_NO = #{routeNo}


  AND R.REG_DATE >= #{startDate}


  AND R.REG_DATE < DATE_ADD(#{endDate}, INTERVAL 1 DAY)

mapper.update:
UPDATE REPORT
SET TYPE_NO = #{typeNo}, ROUTE_NO = #{routeNo}, CONTENT = #{content}
WHERE REPORT_NO = #{reportNo} AND MEMBER_NO = #{memberNo} AND STATUS = 'RECEIVED'
